184	    /// Creates a new GraphQL query builder with the given query.
185	    ///
186	    /// # Arguments
187	    ///
188	    /// * `query` - The GraphQL query string to execute
189	    ///
190	    /// # Returns
191	    ///
192	    /// A [`QueryBuilder`] that can be used to customize and execute the query
193	    pub fn graphql_query<Response>(&self, query: impl Into<String>) -> QueryBuilder<Response> {
194	        let reqwest_builder = self
195	            .http_client
196	            .post(self.gateway_endpoint.clone())
197	            .header(http::header::ACCEPT, "application/json");
198	
199	        QueryBuilder {
200	            query: query.into(),
201	            variables: None,
202	            phantom: PhantomData,
203	            reqwest_builder,
204	        }
205	    }
206	
207	    /// Returns the federated schema as a string.
208	    pub fn federated_graph(&self) -> &str {
209	        &self.federated_graph
210	    }
211	}
